const _p = (typeof parameters !== 'undefined' && parameters) ? parameters : {};
const groupId = _p.config_group_id;
const excludeCrId = _p.exclude_cr_id;
if (!groupId) return { items: [] };
const origin = window.location.origin;
const ws = constants.WS;
const CR_TABLE = constants.CHANGE_REQUESTS_TABLE;
const url = origin + '/api/tooljet-db/proxy/' + CR_TABLE +
  '?status=eq.SUBMITTED&select=id,maker_email,created_at,payload' +
  '&payload->>config_group_id=eq.' + encodeURIComponent(groupId);
const r = await fetch(url, { credentials: 'include', headers: { 'Tj-Workspace-Id': ws } });
if (!r.ok) { console.error('[LOAD_PENDING] http ' + r.status); return { items: [] }; }
const rows = await r.json();
const items = (rows || []).filter(x => String(x.id) !== String(excludeCrId)).map(x => ({
  id: x.id,
  rule_name: (x.payload && x.payload.rule_name) || ('CR #' + x.id),
  maker_email: x.maker_email,
  created_at: x.created_at
}));
return { items };
